import logging
from django.core.cache import cache

logger = logging.getLogger(__name__)
AUDIT_CACHE_TTL = 600


class ContactMaskMixin:
    mask_char = '*'

    def mask_email(self, email: str) -> str:
        local, _, domain = email.partition('@')
        return f'{local[:1]}{self.mask_char * 4}@{domain}'

    def fingerprint(self, value: str) -> str:
        return hashlib.sha256(value.encode('utf-8')).hexdigest()[:12]


class LoginAuditLogger(ContactMaskMixin):
    def record_login(self, customer) -> None:
        masked = self.mask_email(customer.email)
        digest = self.fingerprint(customer.rut)
        logger.info('login customer_id=%s email=%s rut_fp=%s', customer.id, masked, digest)


class CachedLoginAuditLogger(LoginAuditLogger):
    def record_login(self, customer) -> None:
        key = f'login:audit:{customer.id}'
        if cache.get(key):
            logger.info('login audit deduplicated customer_id=%s', customer.id)
            return
        super().record_login(customer)
        cache.set(key, True, AUDIT_CACHE_TTL)

