from datetime import timedelta
from django.utils import timezone
from pydantic import BaseModel

BILLING_RETENTION_DAYS = 2190


class RetentionGuardMixin:
    retention_days = BILLING_RETENTION_DAYS

    def is_expired(self, issued_at, now) -> bool:
        return (now - issued_at).days >= self.retention_days

    def cutoff(self, now):
        return now - timedelta(days=self.retention_days)


class PurgeResult(BaseModel):
    removed: int
    retention_days: int


class BillingPurgeService(RetentionGuardMixin):
    def purge(self, now=None) -> PurgeResult:
        now = now or timezone.now()
        candidates = Invoice.objects.filter(issued_at__lt=self.cutoff(now))
        removed = 0
        for invoice in candidates.iterator():
            if not self.is_expired(invoice.issued_at, now):
                continue
            invoice.delete()
            removed += 1
        return PurgeResult(removed=removed, retention_days=self.retention_days)

