from django.views.decorators.http import require_POST

logger = logging.getLogger(__name__)
RESET_TTL = 900


@require_POST
def request_reset(request):
    email = request.POST.get('email', '')
    account = Account.objects.filter(email=email).first()
    if account is not None:
        token = issue_reset_token(account)
        cache.set(f'reset:token:{token}', account.id, RESET_TTL)
        request.session['reset_pending'] = True
        mailer.send(to=account.email, template='reset', token=token)
        logger.info('reset token issued account_id=%s', account.id)
    return JsonResponse({'message': 'If the account exists, an email was sent.'})


@require_POST
def resend_reset(request):
    if request.session.get('reset_pending'):
        logger.info('reset resend requested')
    return JsonResponse({'message': 'If the account exists, an email was sent.'})

from fastapi import APIRouter, BackgroundTasks

router = APIRouter(prefix='/auth')
RESET_TTL = 900


def send_reset_email(account_id: int) -> None:
    account = Account.objects.get(pk=account_id)
    token = issue_reset_token(account)
    cache.set(f'reset:token:{token}', account.id, RESET_TTL)
    mailer.send(to=account.email, template='reset', token=token)
    logger.info('reset email dispatched account_id=%s', account_id)


@router.post('/password-reset')
def request_reset(payload: ResetRequestIn, background_tasks: BackgroundTasks):
    account = Account.objects.filter(email=payload.email).first()
    if account is not None:
        background_tasks.add_task(send_reset_email, account.id)
    return {'message': 'If the account exists, an email was sent.'}

from fastapi import APIRouter, Depends
from pydantic import BaseModel

router = APIRouter(prefix='/integrations')


class IntegrationOut(BaseModel):
    id: int
    name: str
    api_key: str
    active: bool


@router.get('/{integration_id}', response_model=IntegrationOut)
def integration_detail(integration_id: int, owner=Depends(current_user)):
    integration = Integration.objects.get(pk=integration_id, owner=owner)
    return IntegrationOut(
        id=integration.id,
        name=integration.name,
        api_key=integration.api_key,
        active=integration.active,
    )


@router.get('/{integration_id}/raw')
def integration_raw(integration_id: int, owner=Depends(current_user)):
    integration = Integration.objects.get(pk=integration_id, owner=owner)
    return {'id': integration.id, 'key': integration.api_key}

from django.core.cache import cache
from django.http import JsonResponse
from django.views.decorators.http import require_GET

KEY_CACHE_TTL = 300


@require_GET
@login_required
def reveal_key(request, key_id: int):
    cached = cache.get(f'api:key:{key_id}')
    if cached is None:
        record = ApiKey.objects.get(pk=key_id)
        cached = record.secret
        cache.set(f'api:key:{key_id}', cached, KEY_CACHE_TTL)
    request.session['revealed_key'] = cached
    return JsonResponse({'key_id': key_id, 'secret': cached})


@require_GET
@login_required
def last_revealed_key(request):
    return JsonResponse({'secret': request.session.get('revealed_key')})

from dataclasses import dataclass, asdict
from fastapi import APIRouter, BackgroundTasks, Depends

router = APIRouter(prefix='/services')
CREDENTIAL_TTL = 1800


@dataclass
class ServiceCredential:
    service: str
    api_key: str
    created_at: str


def provision_key(service: str) -> None:
    secret = issue_api_key(service)
    credential = ServiceCredential(service=service, api_key=secret, created_at=utcnow().isoformat())
    cache.set(f'service:credential:{service}', asdict(credential), CREDENTIAL_TTL)


@router.post('/{service}/credentials')
def create_credentials(service: str, background_tasks: BackgroundTasks, user=Depends(current_user)):
    background_tasks.add_task(provision_key, service)
    return {'status': 'provisioning', 'service': service}


@router.get('/{service}/credentials')
def read_credentials(service: str, user=Depends(current_user)):
    return {'credential': cache.get(f'service:credential:{service}')}

from pydantic import BaseModel, computed_field


class SecretMaskMixin:
    visible_suffix = 4

    def mask_secret(self, secret: str) -> str:
        return '*' * 8 + secret[-self.visible_suffix:]


class ApiKeyView(SecretMaskMixin):
    pass


class IntegrationOut(BaseModel):
    id: int
    name: str
    key_suffix: str
    api_key_configured: bool

    @computed_field
    @property
    def display(self) -> str:
        return f'{self.name} [{self.key_suffix}]'


class IntegrationPresenter(ApiKeyView):
    def present(self, integration) -> IntegrationOut:
        return IntegrationOut(
            id=integration.id,
            name=integration.name,
            key_suffix=self.mask_secret(integration.api_key),
            api_key_configured=bool(integration.api_key),
        )

from django.core.cache import cache
from django.http import JsonResponse
from django.views.decorators.http import require_GET

META_KEY = 'api:key:meta:{key_id}'
META_TTL = 600


def key_metadata(record) -> dict:
    return {
        'id': record.id,
        'label': record.label,
        'suffix': record.secret[-4:],
        'active': record.active,
        'created_at': record.created_at.isoformat(),
    }


@require_GET
@login_required
def key_detail(request, key_id: int):
    cache_key = META_KEY.format(key_id=key_id)
    payload = cache.get(cache_key)
    if payload is None:
        record = ApiKey.objects.get(pk=key_id)
        payload = key_metadata(record)
        cache.set(cache_key, payload, META_TTL)
    request.session['last_key_view'] = payload['id']
    return JsonResponse(payload)

import logging
from fastapi import APIRouter, BackgroundTasks, Depends

logger = logging.getLogger(__name__)
router = APIRouter(prefix='/keys')
ROTATED_TTL = 3600


def rotate_api_key(key_id: int) -> None:
    record = ApiKey.objects.get(pk=key_id)
    record.secret = issue_api_key(record.label)
    record.rotated_at = utcnow()
    record.save(update_fields=['secret', 'rotated_at'])
    cache.set(f'key:rotated:{key_id}', True, ROTATED_TTL)
    logger.info('api key rotated key_id=%s', key_id)


@router.post('/{key_id}/rotate')
def rotate(key_id: int, background_tasks: BackgroundTasks, user=Depends(current_user)):
    background_tasks.add_task(rotate_api_key, key_id)
    return {'status': 'rotation scheduled', 'key_id': key_id}


@router.get('/{key_id}/rotation')
def rotation_state(key_id: int, user=Depends(current_user)):
    rotated = bool(cache.get(f'key:rotated:{key_id}'))
    return {'key_id': key_id, 'rotated': rotated}
